<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\DelegateLogin\Infrastructure\Provider;

use Override;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedLoginEndpoint;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedLoginProvider;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedProviderDescription;
use Civi\Lughauth\Features\OAuth\DelegateLogin\Domain\DelegatedUserData;
use Civi\Lughauth\Shared\AppConfig;
use Civi\Lughauth\Shared\Context;
use League\OAuth2\Client\Provider\Google;
use League\OAuth2\Client\Provider\Exception\IdentityProviderException;
use League\OAuth2\Client\Token\AccessToken;

class GoogleOAuthProvider implements DelegatedLoginProvider
{
    private readonly string $assetsPath;

    public function __construct(
        AppConfig $config,
        Context $context,
        private readonly string $id,
        private readonly string $clientId,
        private readonly string $secretId
    ) {
        $this->assetsPath = $config->get('oidc.assets.path', $context->getBaseUrl() . '/oauth/assets/');
    }
    #[Override]
    public function info(): DelegatedProviderDescription
    {
        return new DelegatedProviderDescription(
            id: $this->id,
            name: 'Google',
            logo: $this->assetsPath . '/socials/google.png'
        );
    }
    #[Override]
    public function delegeatedUrl(string $redirect, string $state): DelegatedLoginEndpoint
    {
        if (session_status() !== PHP_SESSION_ACTIVE) {
            session_start();
        }
        $provider = new Google([
            'clientId' => $this->clientId,
            'clientSecret' => $this->secretId,
            'redirectUri' => $redirect,
            'state' => $state
        ]);
        return new DelegatedLoginEndpoint('GET', $provider->getAuthorizationUrl([
            'state' => $state
        ]));
    }

    #[Override]
    public function authorize(string $redirect, array $request): ?DelegatedUserData
    {
        $provider = new Google([
            'clientId' => $this->clientId,
            'clientSecret' => $this->secretId,
            'redirectUri' => $redirect,
        ]);
        try {
            $code = (string) ($request['code'] ?? '');
            if ($code === '') {
                return null;
            }
            $token = $provider->getAccessToken('authorization_code', ['code' => $code]);
            if (!$token instanceof AccessToken) {
                return null;
            }
            /** @var \League\OAuth2\Client\Provider\GoogleUser $user */
            $user = $provider->getResourceOwner($token);
            $data = $user->toArray();
            $sub = (string) ($data['sub'] ?? '');
            $name = (string) ($data['name'] ?? '');
            $email = (string) ($data['email'] ?? '');
            return new DelegatedUserData(
                providerUserId: $sub,
                email: $email,
                name: $name,
                emailVerified: ((bool) ($data['email_verified'] ?? false))
            );
        } catch (IdentityProviderException $ex) {
            return null;
        }
    }
}
